import * as prvaLicka from './prva-licka'
import * as prvaProleterska from './prva-proleterska'
import * as trecaKrajiska from './treca-krajiska'
import type { FallenSpot, Waypoint } from './prva-proleterska'

// The units the map page can show, each generated by scripts/make_unit_route.py from the unit's own book
export type UnitRoute = {
  key: string
  name: string
  genitive: string                                  // "Ratni put Prve proleterske brigade"
  ROUTE: Waypoint[]
  FALLEN: FallenSpot[]
  FALLEN_BY_MONTH: Record<string, number>
  SOURCE: string
  killed: () => Promise<Killed>                     // who they are: only the list page (mapa/spisak) loads it
  battles: string[]                                 // the great battles it fought in (battles.ts), from its book
}

// The soldiers behind the map's counts of the killed (scripts/make_unit_route.py writes them beside each unit)
export type Killed = {
  DATA_FILE: string
  KILLED_BY_MONTH: Record<string, string[]>
  KILLED_AT: Record<string, string[]>[]
}

export const UNIT_ROUTES: UnitRoute[] = [
  { key: 'prva-proleterska', name: 'Prva proleterska brigada', genitive: 'Prve proleterske brigade', ...prvaProleterska,
    killed: () => import('./prva-proleterska-killed'),
    // Ivan-sedlo, Gornji Vakuf and Jablanica; the Sutjeska; Mlinište in the Drvar operation; Belgrade; Šid
    battles: ['neretva', 'sutjeska', 'drvar', 'beograd', 'srem'] },
  { key: 'prva-licka', name: 'Prva lička proleterska brigada „Marko Orešković“',
    genitive: 'Prve ličke proleterske brigade „Marko Orešković“', ...prvaLicka,
    killed: () => import('./prva-licka-killed'),
    // Drvar; the Sava crossing at Zemun; Šid (its "operacija Weiss" was fought in Lika, not at the Neretva)
    battles: ['drvar', 'beograd', 'srem'] },
  { key: 'treca-krajiska', name: 'Treća krajiška proleterska brigada', genitive: 'Treće krajiške proleterske brigade',
    ...trecaKrajiska, killed: () => import('./treca-krajiska-killed'),
    // Gornji Vakuf, Gračanica and Jablanica; the Sutjeska and Zelengora; the Livno–Glamoč road and the Supreme Staff's
    // column in the Drvar operation; Belgrade; Tovarnik, Šid and Novak-Bapska
    battles: ['neretva', 'sutjeska', 'drvar', 'beograd', 'srem'] },
]

// The numbered event's circle on the sheet, in sheet units: the map, its key and the numbers' spacing use it
export const EVENT_R = 9

// A count of the killed on the map opens its list in a new tab: a month's, or a place's (an index into FALLEN), in a
// month or a year of the war: /mapa/spisak?jedinica=prva-licka&mesec=1945-01
export function killedPath(unit: string, at: { month?: string; year?: string; spot?: number }): string {
  const q = new URLSearchParams({ jedinica: unit })
  if (at.spot !== undefined) q.set('mesto', String(at.spot))
  if (at.month) q.set('mesec', at.month)
  else if (at.year) q.set('godina', at.year)
  return `/mapa/spisak?${q}`
}

export type { FallenSpot, Waypoint }
